```c
// scan.c: minimal int scanner for macOS (Apple Silicon / Intel)
// build: clang -O2 -Wall -o scan scan.c
// run:   sudo ./scan <pid> <value>

#include <mach/mach.h>
#include <mach/mach_vm.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>

#define CHUNK (1u << 20)  // read 1 MiB at a time

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "usage: %s <pid> <int-value>\n", argv[0]);
        return 1;
    }

    pid_t pid = (pid_t)strtol(argv[1], NULL, 10);
    int needle = (int)strtol(argv[2], NULL, 10);

    mach_port_t task;
    kern_return_t kr = task_for_pid(mach_task_self(), pid, &task);
    if (kr != KERN_SUCCESS) {
        fprintf(stderr, "task_for_pid(%d) failed: %s\n"
                        "run as root, and make sure the target isn't hardened-runtime signed\n",
                pid, mach_error_string(kr));
        return 1;
    }

    unsigned char *buf = malloc(CHUNK);
    if (!buf) { perror("malloc"); return 1; }

    mach_vm_address_t addr = 0;
    size_t hits = 0;

    for (;;) {
        mach_vm_size_t size = 0;
        vm_region_basic_info_data_64_t info;
        mach_msg_type_number_t count = VM_REGION_BASIC_INFO_COUNT_64;
        mach_port_t obj = MACH_PORT_NULL;

        kr = mach_vm_region(task, &addr, &size, VM_REGION_BASIC_INFO_64,
                            (vm_region_info_t)&info, &count, &obj);
        if (kr != KERN_SUCCESS) break;  // KERN_INVALID_ADDRESS = past the last region

        // game state lives in writable memory; skipping RO/RX regions cuts noise and time
        if ((info.protection & VM_PROT_READ) && (info.protection & VM_PROT_WRITE)) {
            for (mach_vm_size_t off = 0; off < size; off += CHUNK) {
                mach_vm_size_t want = size - off < CHUNK ? size - off : CHUNK;
                mach_vm_size_t got = 0;

                kr = mach_vm_read_overwrite(task, addr + off, want,
                                            (mach_vm_address_t)buf, &got);
                if (kr != KERN_SUCCESS) continue;  // guard pages etc.

                for (mach_vm_size_t i = 0; i + sizeof(int) <= got; i += sizeof(int)) {
                    int v;
                    memcpy(&v, buf + i, sizeof v);
                    if (v == needle) {
                        printf("0x%016llx\n", (unsigned long long)(addr + off + i));
                        hits++;
                    }
                }
            }
        }

        addr += size;
    }

    fprintf(stderr, "%zu hit(s) for %d in pid %d\n", hits, needle, pid);
    free(buf);
    mach_port_deallocate(mach_task_self(), task);
    return 0;
}
```

and a target to point it at, so you can check the answer:

```c
// target.c: clang -O0 -o target target.c && ./target
#include <stdio.h>
#include <unistd.h>

int main(void) {
    volatile int health = 1337;
    printf("pid %d, &health = %p\n", getpid(), (void *)&health);
    for (;;) { sleep(1); }
}
```

```sh
clang -O0 -o target target.c && ./target        # terminal 1
clang -O2 -Wall -o scan scan.c
sudo ./scan <pid-from-target> 1337               # terminal 2
```

how it works: `task_for_pid` gets you the target's mach task port. `mach_vm_region` walks its address map one region at a time, and each readable+writable region gets pulled over in 1 MiB chunks with `mach_vm_read_overwrite` and compared at 4-byte alignment. one of the printed addresses should match the `&health` the target printed. you'll get a few extra hits too, since 1337 shows up in random places.

the mac-specific bit: `task_for_pid` needs root, and it refuses targets signed with hardened runtime. a plain `clang` build is only ad-hoc signed, so `sudo` is enough for your own binary. SIP stays on.

natural next step is a rescan: change `health`, then filter the previous hit list down to addresses that now hold the new value. that's the classic narrowing loop. want me to add it?
